            next_q[3]     = current_q[4];
            next_q[2]     = current_q[3];
            next_q[1]     = current_q[2] ^ feedback; // Tap 2
            next_q[0]     = current_q[1] ^ feedback; // Tap 1
            lfsr_step = next_q;
        end
    endfunction

    integer errors = 0;
    reg [31:0] expected_q;
    integer i;

    initial begin
        // Initialize signals
        reset = 1;
        clk = 0;
        expected_q = 32'h00000001;

