        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Run through 20 meaningful test vectors (clock cycles)
        for (i = 0; i < 20; i = i + 1) begin
            expected_q = lfsr_step(expected_q);
            @(posedge clk);
