            if (q !== expected_q) begin
                $display("ERROR at cycle %0d: Expected %h, got %h", i, expected_q, q);
                errors = errors + 1;
            end
        end

        // Test asynchronous/synchronous reset interruption
        @(posedge clk);
        reset = 1;
        expected_q = 32'h00000001;
        #1;
        if (q !== 32'h00000001) begin
            $display("ERROR: Mid-stream reset failed. Expected 32'h00000001, got %h", q);
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        reset = 0;
        expected_q = lfsr_step(expected_q);
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("ERROR after reset release: Expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
